solutionCode:
def climb_stairs(n):
    previous, current = 1, 1
    for _ in range(2, n + 1):
        previous, current = current, previous + current
    return current

bruteForceCode:
def climb_stairs(n):
    def ways(remaining):
        if remaining <= 1:
            return 1
        return ways(remaining - 1) + ways(remaining - 2)
    return ways(n)
